  "Good decisions start with": "好的决定始于",
  "good answers": "好的答案",
  "Nine short, practical guides for families weighing senior living — what it is, what it costs, how people pay for it, and how to tell if it’s time.": "九份简短实用的指南，帮助正在考虑长者生活社区的家庭了解：它是什么、费用多少、如何支付，以及如何判断时机是否已到。",
  "pages": "页",
  "Is Senior Living the Right Choice?": "长者生活社区是正确的选择吗？",
  "Many families wait for a crisis before they talk about senior living. This guide helps you have the conversation earlier, on your own terms.": "许多家庭要等到危机发生才开始讨论长者生活社区。本指南帮助您以自己的方式，更早地开启这场对话。",
  "Get the free guide": "获取免费指南",
  "Weighing the Senior Living Care Options": "权衡长者生活的护理选择",
  "Independent living, assisted living and memory care are designed for different needs. Knowing the difference makes the choice clearer.": "独立生活、协助生活和记忆护理分别针对不同的需求。了解其中的区别，选择会更加清晰。",
  "Understanding the Cost of Senior Living": "了解长者生活的费用",
  "Monthly rent can look high next to a paid-off mortgage — until you add up everything it replaces.": "与已还清的房贷相比，每月租金看起来可能不低——直到您把它所替代的各项开支加总起来。",
  "{1} Senior Living Funding Sources": "{1}种长者生活资金来源",
  "Most families pay for senior living with a combination of sources. Here are ten worth knowing about.": "大多数家庭会结合多种资金来源支付长者生活费用。以下十种值得了解。",
  "Tips for Funding Senior Living": "长者生活资金筹措建议",
  "Practical tips for planning ahead and making your budget go further.": "提前规划、让预算发挥更大作用的实用建议。",
  "Insurance Options for Senior Living": "长者生活的保险选择",
  "Insurance can help with some senior living costs, but not all. This guide explains what is typically covered.": "保险可以承担部分长者生活费用，但并非全部。本指南说明通常涵盖哪些项目。",
  "VA Aid and Attendance": "VA Aid and Attendance 福利",
  "Aid and Attendance is a VA pension benefit that can help wartime veterans and surviving spouses pay for care.": "Aid and Attendance 是美国退伍军人事务部（VA）的一项养老金福利，可帮助战时退伍军人及其遗孀/鳏夫支付护理费用。",
  "{1} Ways Senior Living Communities Provide Safety & Security": "长者生活社区保障安全的{1}种方式",
  "Safety is one of the main reasons families choose senior living. These are the seven ways a good community provides it.": "安全是家庭选择长者生活社区的主要原因之一。以下是优秀社区保障安全的七种方式。",
  "Staying Social in Senior Living": "在长者生活社区保持社交",
  "Loneliness affects health as much as diet and exercise. Here is how senior living makes staying social easy.": "孤独对健康的影响不亚于饮食和运动。看看长者生活社区如何让保持社交变得轻松。",
  "Run the numbers": "算一算",
  "Senior living vs.": "入住长者社区，还是",
  "staying at home": "留在家中",
  "Add up what home really costs — the mortgage or rent, utilities, upkeep, groceries, transportation and help — and compare it with life here.": "算一算居家的真实花费——房贷或房租、水电煤气、房屋维护、日常食品、交通和帮手费用——再与这里的生活作比较。",
  "Compare the costs": "比较费用",
  "Questions families": "家属常问",
  "ask us": "的问题",
  "Straight answers about living here, care, visiting and moving in. If yours isn’t here, Priya is a phone call away.": "关于在这里生活、护理、探访和入住的直接解答。如果找不到您的问题，只需一通电话即可联系 Priya。",
