  "Do you provide transportation?": "你们提供交通服务吗？",
  "Can I bring my own furniture?": "我可以带自己的家具吗？",
  "Yes, and we hope you will. Apartments are unfurnished so they feel like yours. Our apartments have room for a sectional and a full dining set, and Priya can share floor plans with measurements to help you plan.": "可以，我们也希望您这样做。公寓不配家具，让您住得更有家的感觉。我们的公寓可以放下组合沙发和整套餐桌椅，Priya 还可以提供标有尺寸的户型图，帮助您规划布置。",
  "Can I keep my car?": "我可以保留自己的车吗？",
  "Of course. Residents are welcome to keep a car, and resident parking is available on site. Many residents find they drive less once they discover the scheduled transportation.": "当然可以。欢迎住户保留自己的车，社区内设有住户停车位。许多住户在体验过定时班车服务后，发现自己开车少了很多。",
  "How does mail work?": "邮件如何收取？",
  "Every apartment has its own locking mailbox in the Lobby, with a full street address. The front desk signs for packages and lets you know when something arrives.": "每间公寓在大堂（Lobby）都有一个带锁的专属信箱，并有完整的街道地址。前台会代签包裹，并在物品到达时通知您。",
  "If I need more help later, will I have to move?": "如果以后需要更多帮助，我需要搬走吗？",
  "What is Lantern?": "什么是 Lantern？",
  "Are you licensed?": "你们有执照吗？",
  "Is there a nurse on site?": "社区有护士驻场吗？",
  "What happens in a pre-move-in assessment?": "入住前评估包括什么？",
  "What are visiting hours?": "探访时间是什么时候？",
  "There are none — family and friends are welcome any time. Please sign in at the front desk, which is staffed {1}. After hours, ring the Lobby call box and our team will let you in.": "没有限制——随时欢迎家人和朋友来访。请在前台登记，前台值守时间为{1}。非办公时间请按大堂（Lobby）呼叫器，我们的团队会为您开门。",
  "Can my family join me for a meal?": "家人可以和我一起用餐吗？",
  "Can guests stay overnight?": "客人可以留宿吗？",
  "Yes. Guests are welcome to stay in your apartment for short visits; just let the front desk know so we can welcome them. For longer stays, talk to the Business Office.": "可以。欢迎客人在您的公寓短期留宿；只需告知前台，以便我们接待。如需较长时间留宿，请联系业务办公室。",
  "Where do visitors park?": "访客在哪里停车？",
  "Free visitor parking is right outside the main entrance, with accessible spaces closest to the door and a covered drop-off at the Lobby.": "主入口外即有免费访客停车位，无障碍车位离门口最近，大堂（Lobby）还设有带顶棚的落客区。",
  "Can I visit a resident in Lantern?": "我可以探访 Lantern 的住户吗？",
  "Yes. Families are welcome in Lantern every day. Lantern is a secured neighborhood, so please check in at the Lantern door and a team member will let you in.": "可以。Lantern 每天都欢迎家属探访。Lantern 是安全管理区域，请在 Lantern 门口登记，团队成员会为您开门。",
  "How do I schedule a tour?": "如何预约参观？",
  "What does the move-in process look like?": "入住流程是怎样的？",
  "Is there a deposit or community fee?": "需要支付押金或社区费吗？",
  "Yes, there is a one-time community fee when you reserve an apartment. The amount depends on the apartment and the level of support, and Priya will walk you through the community fee and any current offers during your visit.": "需要。预留公寓时需支付一次性社区费。金额取决于公寓类型和支持级别，Priya 会在您参观时详细说明社区费及当前的优惠活动。",
  "How quickly can I move in?": "最快多久可以入住？",
  "It depends on the apartment you choose. Some apartments are ready now; others have a short waitlist. Priya can tell you exactly what is available today.": "这取决于您选择的公寓。部分公寓现已可入住；其他公寓有简短的候补名单。Priya 可以告诉您目前确切有哪些空房。",
  "Do you help with downsizing and moving?": "你们会协助精简物品和搬家吗？",
  "Yes. We can recommend local senior move managers and movers who know the community well, and our team makes sure your apartment is ready and welcoming on the day.": "会的。我们可以推荐熟悉本社区的当地长者搬迁管理师和搬家公司，我们的团队也会确保您的公寓在入住当天准备就绪、温馨迎人。",
  "Work where you’re": "在您备受",
  "appreciated": "珍视的地方工作",
  "See open positions": "查看空缺职位",
  "Our purpose, shared by every Wrenhaven Senior Living community": "我们的使命，由每一个 Wrenhaven Senior Living 社区共同秉承",
  "Benefits": "福利",
  "Taking care of the people": "照顾那些",
  "who take care": "照顾他人的人",
  "Full-time team members are eligible for the full benefits package. Ask our recruiter about part-time eligibility.": "全职团队成员可享受全套福利。兼职人员的福利资格请咨询我们的招聘专员。",
  "Medical, dental and vision insurance": "医疗、牙科和视力保险",
