  "Paid volunteer time": "带薪志愿服务时间",
  "{1}(k) with company match": "{1}(k) 退休计划（公司配比供款）",
  "Tuition assistance": "学费资助",
  "Paid professional development": "带薪职业发展培训",
  "A free meal every day you work": "每个工作日提供一顿免费餐",
  "How hiring works": "招聘流程",
  "Four steps,": "四个步骤，",
  "no runaround": "简单直接",
  "Apply online": "在线申请",
  "Find the role that suits you and send your application. It takes about ten minutes.": "找到适合您的职位并提交申请，大约只需十分钟。",
  "Recruiter phone screen": "招聘专员电话初筛",
  "A short call with our recruiter to talk about the role, your schedule and your questions.": "与我们的招聘专员简短通话，了解职位、您的时间安排并解答您的疑问。",
  "Community interview": "社区面试",
  "Meet the department director at Alder Bend and see the community for yourself.": "在 Alder Bend 与部门总监见面，亲眼看看我们的社区。",
  "Next steps": "后续步骤",
  "We’ll follow up quickly with an offer or feedback — either way, you’ll hear from us.": "我们会尽快回复，发出录用通知或给予反馈——无论结果如何，您都会收到我们的消息。",
  "Open positions": "空缺职位",
