  "Kestrel Point is owned, designed, built and run by Wrenhaven Senior Living. Our purpose, our six values and where our name comes from.": "Kestrel Point 由 Wrenhaven Senior Living 拥有、设计、建造并运营。了解我们的宗旨、六大价值观以及名字的由来。",
