  "The front entrance of the community": "社区正门入口",
  "By checking this box, I agree to receive recurring automated text messages from Kestrel Point at the mobile number provided, about": "勾选此框，即表示我同意 Kestrel Point 向我提供的手机号码定期发送自动短信，内容涉及",
  "Book an in-person or video tour of Kestrel Point in Rivermead with Community Relations Director Mateo Ruiz.": "与社区关系总监 Mateo Ruiz 预约参观位于 Rivermead 的 Kestrel Point，可选择实地或视频参观。",
  "Tours by appointment": "参观需预约",
  "Stay for lunch": "留下来用午餐",
