  "— live or online — are arranged for residents and visitors who are deaf or hard of hearing, when appropriate. Let us know when you book.": "——现场或线上——可在适当时为失聪或听力障碍的住户及访客安排。预约时请告知我们。",
  "Reasonable accommodations": "合理便利",
  "for people with disabilities, including hearing impairment. Just ask the front desk team.": "为残障人士（包括听力障碍者）提供。请随时向前台团队提出。",
  "Kestrel Point is operated by": "Kestrel Point 的运营方为",
  "Kestrel Point’s accessibility statement: our WCAG 2.1 AA goal, text size, contrast and language tools, ASL interpreters and reasonable accommodations.": "Kestrel Point 无障碍声明：我们以 WCAG 2.1 AA 为目标，提供字号、对比度和语言工具、ASL 手语翻译及合理便利。",
  "Kestrel Point is a home for everyone, and our website, printed materials and community spaces should be too.": "Kestrel Point 是每个人的家，我们的网站、印刷资料和社区空间也应如此。",
  "If you opt in to text messages, Kestrel Point will send you recurring automated texts about the topics you chose — such as your tour, the weekly activity calendar, daily menus, photos and news, Lantern updates or urgent notices.": "如果您选择接收短信，Kestrel Point 将根据您选择的主题定期向您发送自动短信，例如您的参观安排、每周活动日历、每日菜单、照片和新闻、Lantern 动态或紧急通知。",
  "How Kestrel Point and Wrenhaven Senior Living collect, use and protect your information, our cookie policy and SMS terms.": "Kestrel Point 与 Wrenhaven Senior Living 如何收集、使用和保护您的信息，以及我们的 Cookie 政策和短信条款。",
  "Kestrel Point is operated by Wrenhaven Senior Living. This policy explains what we collect when you use our website, how we use it and the choices you have.": "Kestrel Point 由 Wrenhaven Senior Living 运营。本政策说明您使用我们网站时我们收集哪些信息、如何使用这些信息以及您可以做出的选择。",
  "Dimensions are approximate. Layouts vary slightly from apartment to apartment, so Mateo can show you the exact homes that are open.": "尺寸为近似值。各公寓布局略有不同，Mateo 可以带您查看目前可入住的具体房源。",
