  "Monthly base support fee, plus personal care by care plan. Each community confirms pricing after a personal assessment.": "每月基本支持费，另加按护理计划收取的个人护理费用。各社区将在个人评估后确认价格。",
  "Assisted Living Services delivered in every apartment at Wrenhaven communities in Fairhollow and Rivermead, so residents can age in place.": "Wrenhaven 位于 Fairhollow 和 Rivermead 的社区在每套公寓内提供协助生活服务，让住户能够原地养老。",
  "Aging in place": "原地养老",
