  "Lantern Memory Care at Wrenhaven communities in Fairhollow and Rivermead: a home-like, secured neighborhood with its own courtyard, activity team and Events & Adventures.": "Wrenhaven 位于 Fairhollow 和 Rivermead 的社区提供 Lantern 记忆护理：温馨如家、安全封闭的居住区，拥有专属庭院、活动团队和活动与探险项目。",
  "Life at Lantern": "Lantern 的生活",
  "Lantern residents have their own activity team and their own Events & Adventures, with outings beyond the community, and they are welcome at every community event.": "Lantern 住户拥有自己的活动团队和自己的活动与探险项目，包括社区外的出游活动，并欢迎参加每一项社区活动。",
