  "seen and appreciated": "被看见、被认可",
  "Care Partners, chefs, servers, housekeepers, drivers, fitness and activity teams: every role shapes a resident’s day. Join a team that lives its values.": "护理伙伴、厨师、服务员、客房保洁员、司机、健身和活动团队：每个岗位都在影响住户的一天。加入一个践行价值观的团队。",
