  "Visit, meet Colleen and the Care Partner team, and we’ll walk through an assessment together — no pressure and no obligation.": "欢迎前来参观，认识 Colleen 和护理伙伴团队，我们会和您一起完成评估——没有压力，也没有任何义务。",
